package com.arrow.systemui.cc.controller;
import android.content.*;import android.content.pm.PackageManager;import android.hardware.camera2.*;import android.os.*;import java.util.*;
public class FlashlightController { public interface Callback {void onFlashlightChanged(boolean enabled);void onFlashlightError();void onFlashlightAvailabilityChanged(boolean available);} private final Context context;private final CameraManager manager;private final Handler handler=new Handler(Looper.getMainLooper());private final Set<Callback> callbacks=new HashSet<>();private String cameraId;private boolean enabled;
 private final CameraManager.TorchCallback callback=new CameraManager.TorchCallback(){@Override public void onTorchModeChanged(String id,boolean on){if(id.equals(cameraId)){enabled=on;changed(on);}}@Override public void onTorchModeUnavailable(String id){if(id.equals(cameraId)){enabled=false;changed(false);available(false);}}};
 public FlashlightController(Context c){context=c.getApplicationContext();manager=(CameraManager)context.getSystemService(Context.CAMERA_SERVICE);cameraId=findId();try{manager.registerTorchCallback(callback,handler);}catch(Exception ignored){}}
 private String findId(){try{for(String id:manager.getCameraIdList()){CameraCharacteristics x=manager.getCameraCharacteristics(id);if(Boolean.TRUE.equals(x.get(CameraCharacteristics.FLASH_INFO_AVAILABLE))&&Integer.valueOf(CameraCharacteristics.LENS_FACING_BACK).equals(x.get(CameraCharacteristics.LENS_FACING)))return id;}for(String id:manager.getCameraIdList())if(Boolean.TRUE.equals(manager.getCameraCharacteristics(id).get(CameraCharacteristics.FLASH_INFO_AVAILABLE)))return id;}catch(Exception ignored){}return null;}
 public boolean isAvailable(){return cameraId!=null&&context.getPackageManager().hasSystemFeature(PackageManager.FEATURE_CAMERA_FLASH);}public boolean isEnabled(){return enabled;}public boolean setEnabled(boolean on){if(cameraId==null)return false;try{manager.setTorchMode(cameraId,on);enabled=on;changed(on);return true;}catch(Exception e){error();return false;}}public boolean toggle(){return setEnabled(!enabled);}public void addCallback(Callback c){callbacks.add(c);c.onFlashlightAvailabilityChanged(isAvailable());c.onFlashlightChanged(enabled);}public void removeCallback(Callback c){callbacks.remove(c);}public void destroy(){try{manager.unregisterTorchCallback(callback);}catch(Exception ignored){}callbacks.clear();}
 private void changed(boolean v){handler.post(()->{for(Callback c:new HashSet<>(callbacks))c.onFlashlightChanged(v);});}private void available(boolean v){handler.post(()->{for(Callback c:new HashSet<>(callbacks))c.onFlashlightAvailabilityChanged(v);});}private void error(){handler.post(()->{for(Callback c:new HashSet<>(callbacks))c.onFlashlightError();});}
}
